 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    lines = {}  # cell -> colors of crossing rays
    centers = []
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color == 0:
                continue
            if all(grid[rr][cc] == color
                   for rr in range(r, r + 3)
                   for cc in range(c, c + 3)):
                centers.append((r + 1, c + 1, color))
    for cr, cc, color in centers:
        for c in range(w):
            lines.setdefault((cr, c), set()).add(color)
        for r in range(h):
            lines.setdefault((r, cc), set()).add(color)
    out = [row[:] for row in grid]
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out

